CREATE OR REPLACE VIEW `vwprovvdoppie` AS select concat(`p`.`cognome_cliente`,' ',`p`.`nome_cliente`) AS `Cliente`,`p1`.`id_pratica` AS `id_pratica`,(select `tp`.`tipo_prodotto` from `tipoprodotto` `tp` where `tp`.`id` = `p`.`tipoprodotto_id`) AS `tipo_prodotto`,`p1`.`denominazione_riferimento` AS `denominazione_riferimento`,`p1`.`id` AS `n_provvigione`,`p1`.`importo` AS `importo`,`p1`.`data_fattura` AS `data_fattura`,`p2`.`id` AS `n_doppione`,`p2`.`importo` AS `doppione_importo`,`p1`.`status_compenso` AS `status_compenso`,`p1`.`data_status` AS `data_status`,`p1`.`descrizione` AS `descrizione`,`p2`.`data_status` AS `doppione_del`,`p2`.`status_compenso` AS `doppione_status`,`p2`.`data_fattura` AS `fattura_doppione` from ((`provvigioni` `p1` join `pratiches` `p` on((`p`.`id` = `p1`.`pratica_id`))) join `provvigioni` `p2` on(((`p1`.`id_pratica` = `p2`.`id_pratica`) and (`p1`.`tipo` = `p2`.`tipo`) and (`p1`.`denominazione_riferimento` = `p2`.`denominazione_riferimento`) and (`p1`.`descrizione` = `p2`.`descrizione`)))) where ((`p1`.`id` < `p2`.`id`) and (`p1`.`data_fattura` is not null)) order by `p1`.`data_status` desc
